    for(int j=i+1;j<int(x.size());j++)
        for(int k=j+1;k<int(x.size());k++){
            double mean=(x[i]+x[j]+x[k])/3;
            double var=(pow(x[i]-mean,2)+pow(x[j]-mean,2)+pow(x[k]-mean,2))/3;
            if(var<best){best=var;location=mean;}
        }
