for(int i=0;i<=100;i++){
    double intercept=i/10.0,loss=0;
    for(double y:response){
        double error=y-intercept;
        loss+=error>=0?tau*error:(tau-1)*error;
    }
    if(loss<best){best=loss;optimum=intercept;}
}
