#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>loss={0,1,5,10},prob={0.8,0.1,0.05,0.05};
double confidence=0.95,cumulative=0,var=loss.back(),tailMass=1-confidence;
for(int i=0;i<int(loss.size());i++){
    cumulative+=prob[i];
    if(cumulative>=confidence-1e-12){var=loss[i];break;}
}
double remaining=tailMass,upperExpectation=0;
for(int i=int(loss.size())-1;i>=0&&remaining>1e-12;i--){
    double included=min(remaining,prob[i]);
    upperExpectation+=included*loss[i];
    remaining-=included;
}
cout<<"VaR "<<var<<" ES "<<upperExpectation/tailMass<<"
";
return 0;
}

